+      {4, 2},
+      {4, 4},
+      {4, 8},
+      {8, 1},
+      {8, 2},
+      {8, 4},
+      {8, 8},
+      {16, 1},
+      {16, 2},
+      {16, 4},
+      {16, 8},
+      {32, 1},
+      {32, 2},
+      {32, 4},
+      {32, 8},
