+      constexpr auto kCfg = kConfigs[kConfig];
+      constexpr auto kernel = norm_gate_kernel<
+          T,
+          kHeadDim,
+          kCfg.vec_bytes,
+          kCfg.warps_per_block,
+          kHasNorm,
+          kHasWeight,
+          kHasGate,
+          kSingleGroup,
+          kExact,
+          kUsePDL>;
