+                           (static_cast<uint64_t>(cfg.vec_bytes == desired_vec) << 32) |
+                           (static_cast<uint64_t>(1024 - std::min<uint32_t>(distance, 1023)) << 8) |
+                           static_cast<uint64_t>(cfg.vec_bytes);
