+        .x = x.data_ptr(),
+        .gate = nullptr,
+        .weight = weight.has_value() ? weight.value().data_ptr() : nullptr,
+        .y = y.data_ptr(),
+        .gate_stride_token = 0,
+        .gate_stride_group = 0,
+        .num_tokens = num_tokens,
+        .num_heads = static_cast<uint32_t>(num_heads),
+        .heads_per_group = static_cast<uint32_t>(num_heads),
+        .eps = static_cast<float>(eps),
+    };
