+    const auto aligned = [](const void* ptr) { return reinterpret_cast<uintptr_t>(ptr) % kWideBytes == 0; };
+    const auto aligned_elems = [](int64_t elems) { return elems * sizeof(T) % kWideBytes == 0; };
