+  fp32x2_t vals[kPacks][kPairs];
+  fp32x2_t post_w[kPostWeight ? kPacks : 1][kPairs];
+  F32Vec stream_v[kPacks][kFParts];
+  F32Vec alpha_pf[kPreSlots][kFParts], beta_pf[kPreSlots][kFParts];
