+        new_s.x = s.x + normed_b.x;
+        new_s.y = s.y + normed_b.y;
+      }
+      new_stream_v[h][l] = new_s;
+      const fp32x2_t pre_v = pre_bf16 ? round_bf16(new_s) : new_s;
