+
+  float4 acc[kMaxTokens];
+#pragma unroll
+  for (int t = 0; t < kMaxTokens; ++t)
+    acc[t] = make_float4(0.f, 0.f, 0.f, 0.f);
+
+#pragma unroll
+  for (int i = 0; i < kIters; ++i) {
+    const int kk = phase + i * kPhases;
