+    const dim3 grid(kSplitK, static_cast<unsigned>(n_tiles));
+    LaunchKernel(grid, kThreads, device_.unwrap())
+        .enable_pdl(kUsePDL)(
+            muse_spark_router_gemm_kernel<kMaxTokens, kHidden, kSplitK, kNTile, kThreads, kUsePDL>, params);
+  }
+};
